import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyThongBaoCuDan = () => {
    const [notifications, setNotifications] = useState([]);
    const [loading, setLoading] = useState(true); // Tối ưu: Thêm trạng thái chờ Backend
    const [userRoom, setUserRoom] = useState('');

    useEffect(() => {
        const fetchData = async () => {
            setLoading(true);
            try {
                // 1. Lấy Profile (Sau này: const res = await axios.get('/api/me'))
                const savedProfile = localStorage.getItem('userProfile');
                let currentRoom = '';
                if (savedProfile) {
                    const parsedProfile = JSON.parse(savedProfile);
                    currentRoom = parsedProfile.room_id || parsedProfile.room;
                    setUserRoom(currentRoom);
                }

                // 2. Lấy Thông báo (Sau này: const res = await axios.get('/api/notifications'))
                const savedNotis = localStorage.getItem('building_notifications');
                if (savedNotis) {
                    const allNotis = JSON.parse(savedNotis);

                    // 3. Tối ưu Filter: Backend sau này sẽ xử lý việc này, 
                    // nhưng hiện tại ta lọc ở Front-end dựa trên room_id chuẩn
                    const filteredNotis = allNotis.filter(noti => 
                        noti.room === 'All' || String(noti.room) === String(currentRoom)
                    );
                    setNotifications(filteredNotis);
                }
            } catch (error) {
                console.error("Lỗi kết nối dữ liệu:", error);
            } finally {
                setLoading(false); // Kết thúc tải dữ liệu
            }
        };

        fetchData();
    }, []);

    // Hiệu ứng Loading khi chờ Backend phản hồi
    if (loading) return (
        <div style={{...containerStyle, justifyContent: 'center', alignItems: 'center'}}>
            <div style={{color: '#fff', fontSize: '18px'}}>Đang tải thông báo...</div>
        </div>
    );

    return (
        <div style={containerStyle} className="glass-card">
            <div style={headerStyle}>
                <div>
                    <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>📢 THÔNG BÁO TÒA NHÀ</h2>
                    <p style={{ color: 'rgba(255,255,255,0.7)', margin: '5px 0 0 0', fontSize: '12px' }}>Dữ liệu đã được đồng bộ hệ thống</p>
                </div>
                {userRoom && <div style={roomTagHeader}>Phòng: {userRoom}</div>}
            </div>

            <div style={{ flex: 1, padding: '20px', overflow: 'hidden' }}>
                <div className="custom-scrollbar" style={scrollContainerStyle}>
                    {notifications.length > 0 ? (
                        notifications.map(noti => (
                            <div key={noti.id} style={notiCardStyle}>
                                <div style={notiHeaderRow}>
                                    <span style={{
                                        ...roomTagStyle, 
                                        backgroundColor: noti.room === 'All' ? '#333' : '#8b5e5e'
                                    }}>
                                        {noti.room === 'All' ? 'CHUNG' : 'GỬI RIÊNG'}
                                    </span>
                                    <span style={dateStyle}>{noti.date}</span>
                                </div>
                                <h3 style={titleStyle}>{noti.title}</h3>
                                <p style={bodyStyle}>{noti.body}</p>
                            </div>
                        ))
                    ) : (
                        <div style={emptyStateStyle}>Hiện tại không có thông báo nào.</div>
                    )}
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 5px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.2); border-radius: 10px; }
            `}</style>
        </div>
    );
};

// --- STYLES GIỮ NGUYÊN NHƯ TRƯỚC ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(0,0,0,0.3)', borderBottom: '1px solid rgba(255,255,255,0.1)' };
const roomTagHeader = { backgroundColor: 'rgba(139, 94, 94, 0.8)', color: '#fff', padding: '6px 15px', borderRadius: '12px', fontSize: '14px', fontWeight: 'bold' };
const scrollContainerStyle = { height: '100%', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px' };
const notiCardStyle = { backgroundColor: 'rgba(255,255,255,0.95)', padding: '18px', borderRadius: '20px', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' };
const notiHeaderRow = { display: 'flex', justifyContent: 'space-between', marginBottom: '10px' };
const roomTagStyle = { color: '#fff', padding: '3px 10px', borderRadius: '6px', fontSize: '10px', fontWeight: 'bold' };
const dateStyle = { fontSize: '11px', color: '#aaa' };
const titleStyle = { margin: '0 0 8px 0', fontSize: '17px', color: '#222' };
const bodyStyle = { margin: 0, fontSize: '14px', color: '#555', lineHeight: '1.5' };
const emptyStateStyle = { textAlign: 'center', color: '#fff', marginTop: '100px', opacity: 0.8 };

export default QuanLyThongBaoCuDan;
